\begin{tikzpicture}[font=\sffamily, line width=0.8pt, >=stealth]
  % beaker of dilute sodium chloride solution
  \dotregion{0}{0}{7}{2.6}
  \draw[thick] (0,3.2) -- (0,0) -- (7,0) -- (7,3.2);
  \draw (0,2.6) -- (1.6,2.6) (2.9,2.6) -- (4.6,2.6) (5.9,2.6) -- (7,2.6);

  % left test tube over the anode: gas level top, liquid inside lower
  \dotregion{1.6}{0.9}{2.9}{2.8}
  \fill[white] (1.6,2.8) rectangle (2.9,3.8);
  \draw (1.6,2.8) -- (2.9,2.8);
  \draw[thick] (1.6,0.9) -- (1.6,3.8) -- (2.9,3.8) -- (2.9,0.9);

  % right test tube over the cathode: more gas, so the liquid level is lower
  \dotregion{4.6}{0.9}{5.9}{1.8}
  \fill[white] (4.6,1.8) rectangle (5.9,3.8);
  \draw (4.6,1.8) -- (5.9,1.8);
  \draw[thick] (4.6,0.9) -- (4.6,3.8) -- (5.9,3.8) -- (5.9,0.9);

  % carbon electrodes through the bottom of the beaker
  \draw[line width=1.5pt] (2.25,-1.0) -- (2.25,1.4);
  \draw[line width=1.5pt] (5.25,-1.0) -- (5.25,1.4);

  % bubbles rising from the electrodes
  \draw[fill=white] (2.0,2.0) circle (0.07);
  \draw[fill=white] (2.45,2.15) circle (0.07);
  \draw[fill=white] (2.1,2.5) circle (0.07);
  \draw[fill=white] (4.95,1.5) circle (0.07);
  \draw[fill=white] (5.45,1.55) circle (0.07);
  \draw[fill=white] (5.2,1.68) circle (0.07);

  % wires to the battery: left electrode to positive, right electrode to negative
  \draw (2.25,-1.0) -- (2.25,-2.6) -- (3.2,-2.6) -- (3.2,-3.6);
  \draw (5.25,-1.0) -- (5.25,-2.6) -- (4.3,-2.6) -- (4.3,-3.6);
  \draw[thick] (2.75,-3.6) rectangle (4.75,-4.1);
  \node at (2.85,-3.1) {$+$};
  \node at (4.65,-3.1) {$-$};

  % labels
  \node[left] at (2.25,-0.4) {anode};
  \node[right] at (5.25,-0.4) {cathode};
  \node at (2.25,3.3) {gas X};
  \node at (5.25,2.8) {gas Y};
  \draw (6.6,1.3) -- (7.4,1.3) node[right] {dilute sodium chloride solution};

  % caption
  \node at (3.5,-5.0) {Fig. 3.1};
\end{tikzpicture}
